-- Generated by Murakumo: load tpch_erp.part (append), without Murakumo. Run it from the project folder.

-- The files under landing/tpch_erp/part/ that were not loaded before.
create or replace temp table new_rows as
select cast(p_partkey as BIGINT) as p_partkey, cast(p_name as VARCHAR) as p_name, cast(p_mfgr as VARCHAR) as p_mfgr, cast(p_brand as VARCHAR) as p_brand, cast(p_type as VARCHAR) as p_type, cast(p_size as INTEGER) as p_size, cast(p_container as VARCHAR) as p_container, cast(p_retailprice as DECIMAL(15,2)) as p_retailprice, cast(p_comment as VARCHAR) as p_comment, filename
from read_json('landing/tpch_erp/part/part_*.jsonl', format = 'newline_delimited', filename = true, columns = {'p_partkey': 'BIGINT', 'p_name': 'VARCHAR', 'p_mfgr': 'VARCHAR', 'p_brand': 'VARCHAR', 'p_type': 'VARCHAR', 'p_size': 'INTEGER', 'p_container': 'VARCHAR', 'p_retailprice': 'DECIMAL(15,2)', 'p_comment': 'VARCHAR'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'part');
-- Append: the new files' rows are added.
insert into raw_tpch_erp.part (p_partkey, p_name, p_mfgr, p_brand, p_type, p_size, p_container, p_retailprice, p_comment, _ingested_at, _batch_id)
select p_partkey, p_name, p_mfgr, p_brand, p_type, p_size, p_container, p_retailprice, p_comment, now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'part', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
